    student VARCHAR(255),
    class VARCHAR(255),
    PRIMARY KEY (student, class)
);

solutions.query:
SELECT DISTINCT c.class
FROM Courses c
WHERE (SELECT COUNT(*) FROM Courses c2 WHERE c2.class = c.class) >= 5;

SELECT DISTINCT class
FROM (
    SELECT class, COUNT(*) OVER (PARTITION BY class) AS class_size
    FROM Courses
) t
WHERE class_size >= 5;

