SELECT ROUND(SUM(i.tiv_2016), 2) AS tiv_2016
FROM Insurance i
WHERE EXISTS (
    SELECT 1 FROM Insurance a
    WHERE a.tiv_2015 = i.tiv_2015 AND a.pid <> i.pid
)
AND NOT EXISTS (
    SELECT 1 FROM Insurance b
    WHERE b.lat = i.lat AND b.lon = i.lon AND b.pid <> i.pid
);

