Delete Duplicate Emails.schema:
CREATE TABLE Person (
    id INT PRIMARY KEY,
    email VARCHAR(255)
);

solutions.query:
DELETE FROM Person
WHERE id NOT IN (
    SELECT keeper FROM (
        SELECT MIN(id) AS keeper FROM Person GROUP BY email
    ) AS t
);

DELETE p1 FROM Person p1
INNER JOIN Person p2 ON p1.email = p2.email
WHERE p1.id > p2.id;

DELETE FROM Person
WHERE id IN (
    SELECT id FROM (
        SELECT id, ROW_NUMBER() OVER (PARTITION BY email ORDER BY id) AS rn
        FROM Person
    ) AS ranked
    WHERE rn > 1
);

